-- Parting code keys (Code keys -> Parting) from the Groove-Turn catalog's
-- parting families, each with its designation decoder for inserts and tools:
-- TANG-GRIP, PENTA, GIM, BGM and GFT (kept if they exist); DO-GRIP gets the XL
-- part and the tool sections it doesn't have yet (by section key). Meanings
-- read off the designations rather than stated in the catalog say "(inferred)".

INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.tanggrip', $ck${"title": "TANG-GRIP code key – inserts and tools", "subtitle": "Tangentially clamped single-ended inserts (TAG) and their blades, tools and adapters", "example": "TAG R3C-15D", "decoder": "tang-grip", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "TAG", "rows": [{"code": "TAG", "meaning": "TANG-GRIP single-ended insert"}]}, {"key": "i-hand", "title": "Hand of insert", "rows": [{"code": "N", "meaning": "Neutral"}, {"code": "R", "meaning": "Right"}, {"code": "L", "meaning": "Left"}], "sample": "R"}, {"key": "i-width", "title": "Insert – cutting width", "sample": "3", "rows": [{"code": "#", "meaning": "Cutting width in mm (e.g. 3, 2.4, 6.3)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "C", "rows": [{"code": "C", "meaning": "Parting, grooving and slitting bars, hard materials and tough applications"}, {"code": "CB", "meaning": "C type with larger corner radii, for interrupted cut and high feed"}, {"code": "M", "meaning": "Similar to C, with a modified edge – improved chip control at medium feeds"}, {"code": "W", "meaning": "Bars, hard materials and tough applications (TAG N-C/W/M)"}, {"code": "HF", "meaning": "High feed parting & grooving, hard materials and tough applications"}, {"code": "MF", "meaning": "Stainless and alloy steel at medium feed"}, {"code": "J", "meaning": "Soft materials, tubes, small diameters and thin-walled parts"}, {"code": "JS", "meaning": "J with sharp corners (not for TGSF slitting cutters)"}, {"code": "JT", "meaning": "Soft materials (J/JS/JT family)"}, {"code": "LF", "meaning": "Stainless steel"}, {"code": "UT", "meaning": "Low feeds on Cr-Ni alloys, ductile materials & low carbon steel"}, {"code": "A", "meaning": "Aluminum"}, {"code": "T", "meaning": "Ductile materials, steel and stainless steel"}]}, {"key": "i-lead", "title": "Lead angle", "rows": [{"code": "#D", "meaning": "Lead angle in degrees (e.g. 6D = 6°)"}, {"code": "##D", "meaning": "Lead angle in degrees (e.g. 15D = 15°)"}], "sample": "15D"}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "TGFH", "meaning": "Blades with tangential pockets (TGFH, TGFHR/L reinforced, -S single-sided, -JHP, -MB, TGFHL-TR)"}, {"code": "TGFS", "meaning": "Blades for multi-spindle machines (replacing HSS and brazed tools)"}, {"code": "TGSU", "meaning": "Flat top blades with tangential pockets"}, {"code": "TGT", "meaning": "Integral shank tools (TGTR / TGTL: -IQ, -JHP, -JHP-MC, -D, 2Z…)"}, {"code": "TGAD", "meaning": "Adapters (TGAD …N, TGAD RE/LE-JHP)"}, {"code": "TAGPAD", "meaning": "Adapters with high-pressure coolant channels (TAGPAD-JHP, TAGPAD-XL-JHP)"}, {"code": "TGAQ", "meaning": "Square adapters (LOGIQ-F-GRIP)"}, {"code": "ADMP", "meaning": "Adapters with 5 pockets (ADMP D45)"}, {"code": "THMP", "meaning": "Holders for pentagonal adapters (THMPR/L D45-JHP)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}, {"code": "R/L", "meaning": "Right- or left-hand"}, {"code": "N", "meaning": "Neutral"}, {"code": "RE", "meaning": "Right-hand, E type (RE/LE adapters) (inferred)"}, {"code": "LE", "meaning": "Left-hand, E type (RE/LE adapters) (inferred)"}, {"code": "R/LE", "meaning": "Right- or left-hand, E type (inferred)"}]}, {"key": "t-angle", "title": "Tool – angle a° (multi-spindle blades)", "rows": [{"code": "#", "meaning": "Angle a° (0 or 5)"}]}, {"key": "t-height", "title": "Tool – blade height / shank", "rows": [{"code": "##", "meaning": "Blade height or shank size in mm (e.g. 26, 32)"}, {"code": "###", "meaning": "Blade height in mm (e.g. 100, 150)"}, {"code": "####", "meaning": "Shank height x width in mm (e.g. 2525 = 25 x 25)"}]}, {"key": "t-width", "title": "Tool – insert width (seat)", "rows": [{"code": "#", "meaning": "Insert width in mm (the seat's insert, e.g. 3)"}]}, {"key": "t-dia", "title": "Tool – D size", "rows": [{"code": "D##", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D24, D52) (inferred)"}, {"code": "D###", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D120) (inferred)"}]}, {"key": "t-pockets", "title": "Tool – pockets", "rows": [{"code": "#Z", "meaning": "Number of pockets (e.g. 2Z, 4Z)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "JHP", "meaning": "Channels for high-pressure coolant"}, {"code": "MC", "meaning": "Bottom inlets for the high-pressure coolant"}, {"code": "K", "meaning": "With coolant holes (10 bar min.; cooling tube SGCU 341 ordered separately)"}, {"code": "C", "meaning": "With coolant – frontal coolant holes (JETCUT) / internal coolant"}, {"code": "XL", "meaning": "Extra long"}, {"code": "SH", "meaning": "Short head (CNC and Swiss automatics)"}, {"code": "S", "meaning": "Single-sided blade (e.g. TGFH-S) / for next to high shoulders (e.g. PCHRS)"}, {"code": "IQ", "meaning": "IQ line (e.g. TGTR/L-IQ, PCHR/L-D-IQ)"}, {"code": "TR", "meaning": "For TRAUB and Index machines"}, {"code": "MB", "meaning": "For other manufacturers' blocks"}, {"code": "B", "meaning": "B type, e.g. DGTR/L-B-D (reinforced) / DGAD-B-D (screw-clamped) (inferred)"}, {"code": "L###", "meaning": "Tool length in mm (e.g. L120)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;

INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.penta', $ck${"title": "PENTA code key – inserts and tools", "subtitle": "Inserts with 5 cutting edges: PENTA 17 / 24 / 34 (PENTA-CUT, QUICK-PENTA) and PENTA D (PENTA IQ GRIP)", "example": "PENTA 24R150J15D", "decoder": "penta", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "PENTA", "rows": [{"code": "PENTA", "meaning": "Pentagonal insert with 5 cutting edges"}]}, {"key": "i-size", "title": "Insert – size", "sample": "24", "rows": [{"code": "17", "meaning": "PENTA 17 (PENTA-CUT)"}, {"code": "24", "meaning": "PENTA 24 (PENTA-CUT / QUICK-PENTA)"}, {"code": "34", "meaning": "PENTA 34 (PENTA-CUT)"}, {"code": "D22", "meaning": "PENTA D, size 22 (PENTA IQ GRIP)"}, {"code": "D32", "meaning": "PENTA D, size 32 (PENTA IQ GRIP)"}, {"code": "D40", "meaning": "PENTA D, size 40 (PENTA IQ GRIP)"}]}, {"key": "i-hand", "title": "Hand of insert", "rows": [{"code": "N", "meaning": "Neutral"}, {"code": "R", "meaning": "Right"}, {"code": "L", "meaning": "Left"}], "sample": "R"}, {"key": "i-width", "title": "Insert – cutting width (x100 mm)", "sample": "150", "rows": [{"code": "###", "meaning": "Cutting width x 100 (e.g. 150 = 1.50 mm, 300 = 3.00 mm)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "J", "rows": [{"code": "C", "meaning": "Parting (and grooving) bars, hard materials and tough applications"}, {"code": "J", "meaning": "Soft materials, tubes, small and thin-walled parts"}, {"code": "Z", "meaning": "Tubes, small and thin-walled parts"}, {"code": "P", "meaning": "Soft materials, thin walls and miniature parts"}, {"code": "PB", "meaning": "Bearing steel and other ductile materials"}, {"code": "PF", "meaning": "High positive flat rake – parting and precision grooving"}, {"code": "NF", "meaning": "Quick cutting edge indexing, next to high shoulders (QUICK-PENTA)"}, {"code": "B", "meaning": "Soft & ductile materials such as 100Cr6 (bearing industry), low to medium feeds"}]}, {"key": "i-radius", "title": "Insert – corner radius (x100 mm)", "rows": [{"code": "###", "meaning": "Corner radius x 100 (e.g. 020 = 0.20 mm; 000 = sharp)"}]}, {"key": "i-lead", "title": "Lead angle", "rows": [{"code": "#D", "meaning": "Lead angle in degrees (e.g. 6D = 6°)"}, {"code": "##D", "meaning": "Lead angle in degrees (e.g. 15D = 15°)"}], "sample": "15D"}, {"key": "i-side", "title": "Insert – side version", "rows": [{"code": "RS", "meaning": "Right side version (next to a shoulder) (inferred)"}, {"code": "LS", "meaning": "Left side version (next to a shoulder) (inferred)"}, {"code": "R/LS", "meaning": "Right or left side version (inferred)"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "PCH", "meaning": "Grooving, parting and recessing tools (PCHR/L, PCHRS/LS next to shoulders, -JHP, -MC, -QC, -D-IQ)"}, {"code": "PCHB", "meaning": "Double-ended parting and grooving blades (PCHBR/L)"}, {"code": "PCAD", "meaning": "Adapters (PCADR/L, -JHP, 34N-RE reinforced, 24-JHP-QC QUICK-PENTA)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}, {"code": "R/L", "meaning": "Right- or left-hand"}, {"code": "N", "meaning": "Neutral"}, {"code": "RE", "meaning": "Right-hand, E type (RE/LE adapters) (inferred)"}, {"code": "LE", "meaning": "Left-hand, E type (RE/LE adapters) (inferred)"}, {"code": "R/LE", "meaning": "Right- or left-hand, E type (inferred)"}]}, {"key": "t-angle", "title": "Tool – angle a° (multi-spindle blades)", "rows": [{"code": "#", "meaning": "Angle a° (0 or 5)"}]}, {"key": "t-height", "title": "Tool – blade height / shank", "rows": [{"code": "##", "meaning": "Blade height or shank size in mm (e.g. 26, 32)"}, {"code": "###", "meaning": "Blade height in mm (e.g. 100, 150)"}, {"code": "####", "meaning": "Shank height x width in mm (e.g. 2525 = 25 x 25)"}]}, {"key": "t-width", "title": "Tool – insert width (seat)", "rows": [{"code": "#", "meaning": "Insert width in mm (the seat's insert, e.g. 3)"}]}, {"key": "t-dia", "title": "Tool – D size", "rows": [{"code": "D##", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D24, D52) (inferred)"}, {"code": "D###", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D120) (inferred)"}]}, {"key": "t-pockets", "title": "Tool – pockets", "rows": [{"code": "#Z", "meaning": "Number of pockets (e.g. 2Z, 4Z)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "JHP", "meaning": "Channels for high-pressure coolant"}, {"code": "MC", "meaning": "Bottom inlets for the high-pressure coolant"}, {"code": "K", "meaning": "With coolant holes (10 bar min.; cooling tube SGCU 341 ordered separately)"}, {"code": "C", "meaning": "With coolant – frontal coolant holes (JETCUT) / internal coolant"}, {"code": "XL", "meaning": "Extra long"}, {"code": "SH", "meaning": "Short head (CNC and Swiss automatics)"}, {"code": "S", "meaning": "Single-sided blade (e.g. TGFH-S) / for next to high shoulders (e.g. PCHRS)"}, {"code": "IQ", "meaning": "IQ line (e.g. TGTR/L-IQ, PCHR/L-D-IQ)"}, {"code": "TR", "meaning": "For TRAUB and Index machines"}, {"code": "MB", "meaning": "For other manufacturers' blocks"}, {"code": "B", "meaning": "B type, e.g. DGTR/L-B-D (reinforced) / DGAD-B-D (screw-clamped) (inferred)"}, {"code": "L###", "meaning": "Tool length in mm (e.g. L120)"}, {"code": "QC", "meaning": "QUICK-PENTA quick cutting edge indexing (safety lock)"}, {"code": "RE", "meaning": "Reinforced"}, {"code": "#", "meaning": "Tool variant after the PENTA size (e.g. PCHR 16-24-5) – see the catalog"}]}, {"key": "t-penta", "title": "Tool – PENTA size seat", "rows": [{"code": "##", "meaning": "For PENTA 17 / 24 / 34 inserts"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;

INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.gim', $ck${"title": "GIM code key – utility inserts (CUT-GRIP)", "subtitle": "Single-sided screw-clamped utility inserts for parting and grooving", "example": "GIM 2.2JS-15RA", "decoder": "gim", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "GIM", "rows": [{"code": "GIM", "meaning": "Utility single-sided insert (CUT-GRIP)"}]}, {"key": "i-width", "title": "Insert – cutting width", "sample": "2.2", "rows": [{"code": "#", "meaning": "Cutting width in mm (e.g. 3, 2.2, 4.6)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "J", "rows": [{"code": "J", "meaning": "Soft materials, tubes, small diameters and thin-walled parts"}, {"code": "C", "meaning": "Bars, hard materials and tough applications"}, {"code": "W", "meaning": "Central ridged chipformer and reinforced edge"}, {"code": "UT", "meaning": "Low feeds on CrNi alloys"}], "note": "No chipformer letter: plain insert (e.g. GIM 3)."}, {"key": "i-sharp", "title": "Sharp corners", "sample": "S", "rows": [{"code": "S", "meaning": "Sharp corners (e.g. JS)"}]}, {"key": "i-lead", "title": "Lead angle and hand", "sample": "15RA", "rows": [{"code": "#RA", "meaning": "Lead angle in degrees, right-hand (e.g. 8RA)"}, {"code": "#LA", "meaning": "Lead angle in degrees, left-hand"}, {"code": "##RA", "meaning": "Lead angle in degrees, right-hand (e.g. 15RA)"}, {"code": "##LA", "meaning": "Lead angle in degrees, left-hand"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;

INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.bgm', $ck${"title": "BGM code key – narrow inserts", "subtitle": "Narrow, material cost saving inserts for grooving and parting up to 20 mm bar diameters, and their tools", "example": "BGM R1001J-15D", "decoder": "bgm", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "BGM", "rows": [{"code": "BGM", "meaning": "Narrow insert"}]}, {"key": "i-hand", "title": "Hand of insert", "rows": [{"code": "N", "meaning": "Neutral"}, {"code": "R", "meaning": "Right"}, {"code": "L", "meaning": "Left"}], "sample": "R"}, {"key": "i-width", "title": "Insert – cutting width (x10 mm)", "sample": "10", "rows": [{"code": "##", "meaning": "Cutting width x 10 (e.g. 10 = 1.0 mm, 08 = 0.8 mm)"}]}, {"key": "i-radius", "title": "Insert – corner radius (x10 mm)", "sample": "01", "rows": [{"code": "##", "meaning": "Corner radius x 10 (e.g. 01 = 0.1 mm)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "J", "rows": [{"code": "J", "meaning": "Grooving and parting (soft materials)"}]}, {"key": "i-lead", "title": "Lead angle", "rows": [{"code": "#D", "meaning": "Lead angle in degrees (e.g. 6D = 6°)"}, {"code": "##D", "meaning": "Lead angle in degrees (e.g. 15D = 15°)"}], "sample": "15D"}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "BGT", "meaning": "Integral shank tools with coolant channels for narrow inserts (BGTR / BGTL-B-JHP)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}, {"code": "R/L", "meaning": "Right- or left-hand"}, {"code": "N", "meaning": "Neutral"}, {"code": "RE", "meaning": "Right-hand, E type (RE/LE adapters) (inferred)"}, {"code": "LE", "meaning": "Left-hand, E type (RE/LE adapters) (inferred)"}, {"code": "R/LE", "meaning": "Right- or left-hand, E type (inferred)"}]}, {"key": "t-angle", "title": "Tool – angle a° (multi-spindle blades)", "rows": [{"code": "#", "meaning": "Angle a° (0 or 5)"}]}, {"key": "t-height", "title": "Tool – blade height / shank", "rows": [{"code": "##", "meaning": "Blade height or shank size in mm (e.g. 26, 32)"}, {"code": "###", "meaning": "Blade height in mm (e.g. 100, 150)"}, {"code": "####", "meaning": "Shank height x width in mm (e.g. 2525 = 25 x 25)"}]}, {"key": "t-width", "title": "Tool – insert width (seat)", "rows": [{"code": "#", "meaning": "Insert width in mm (the seat's insert, e.g. 3)"}]}, {"key": "t-dia", "title": "Tool – D size", "rows": [{"code": "D##", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D24, D52) (inferred)"}, {"code": "D###", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D120) (inferred)"}]}, {"key": "t-pockets", "title": "Tool – pockets", "rows": [{"code": "#Z", "meaning": "Number of pockets (e.g. 2Z, 4Z)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "JHP", "meaning": "Channels for high-pressure coolant"}, {"code": "MC", "meaning": "Bottom inlets for the high-pressure coolant"}, {"code": "K", "meaning": "With coolant holes (10 bar min.; cooling tube SGCU 341 ordered separately)"}, {"code": "C", "meaning": "With coolant – frontal coolant holes (JETCUT) / internal coolant"}, {"code": "XL", "meaning": "Extra long"}, {"code": "SH", "meaning": "Short head (CNC and Swiss automatics)"}, {"code": "S", "meaning": "Single-sided blade (e.g. TGFH-S) / for next to high shoulders (e.g. PCHRS)"}, {"code": "IQ", "meaning": "IQ line (e.g. TGTR/L-IQ, PCHR/L-D-IQ)"}, {"code": "TR", "meaning": "For TRAUB and Index machines"}, {"code": "MB", "meaning": "For other manufacturers' blocks"}, {"code": "B", "meaning": "B type, e.g. DGTR/L-B-D (reinforced) / DGAD-B-D (screw-clamped) (inferred)"}, {"code": "L###", "meaning": "Tool length in mm (e.g. L120)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;

INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.gft', $ck${"title": "GFT code key – thin inserts", "subtitle": "Thin parting, grooving & slitting single-ended inserts", "example": "GFT 1.2J-0.14", "decoder": "gft", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "GFT", "rows": [{"code": "GFT", "meaning": "Thin single-ended insert"}]}, {"key": "i-width", "title": "Insert – cutting width", "sample": "1.2", "rows": [{"code": "#", "meaning": "Cutting width in mm (e.g. 0.8, 1.2, 1.6)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "J", "rows": [{"code": "J", "meaning": "Soft materials"}], "note": "No chipformer letter: plain insert (e.g. GFT 1.2)."}, {"key": "i-radius", "title": "Insert – corner radius", "sample": "0.14", "rows": [{"code": "#", "meaning": "Corner radius in mm (e.g. 0.14)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;

UPDATE "AppSetting" a
SET "value" = jsonb_set(a."value"::jsonb, '{sections}', (a."value"::jsonb -> 'sections') || COALESCE((
  SELECT jsonb_agg(s) FROM jsonb_array_elements($ck$[{"key": "dg-xl", "title": "Extra long (optional)", "rows": [{"code": "XL", "meaning": "Extra long insert – parting bars up to 65 mm diameter"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "DGFH", "meaning": "Blades carrying DO-GRIP (and HELI-GRIP) inserts (DGFH, DGFHR/L reinforced, -JHP, DGFHL-…-TR)"}, {"code": "DGFS", "meaning": "Blades for multi-spindle machines (replacing HSS and brazed tools)"}, {"code": "DGT", "meaning": "Integral shank tools (DGTR / DGTL: -B-D-SH, -B-D-JHP-SL, -B-T-SH, -XL…)"}, {"code": "DGAD", "meaning": "Adapters for DO-GRIP double-ended inserts (DGAD …N, -B-D screw-clamped, RE/LE-JHP)"}, {"code": "HGAD", "meaning": "Adapters (HGAD) for 3 mm twisted inserts"}, {"code": "DGPAD", "meaning": "Adapters with coolant channels (DGPAD-JHP, DGPAD-XL-JHP)"}, {"code": "DGAQ", "meaning": "Square adapters (LOGIQ-F-GRIP)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}, {"code": "R/L", "meaning": "Right- or left-hand"}, {"code": "N", "meaning": "Neutral"}, {"code": "RE", "meaning": "Right-hand, E type (RE/LE adapters) (inferred)"}, {"code": "LE", "meaning": "Left-hand, E type (RE/LE adapters) (inferred)"}, {"code": "R/LE", "meaning": "Right- or left-hand, E type (inferred)"}]}, {"key": "t-angle", "title": "Tool – angle a° (multi-spindle blades)", "rows": [{"code": "#", "meaning": "Angle a° (0 or 5)"}]}, {"key": "t-height", "title": "Tool – blade height / shank", "rows": [{"code": "##", "meaning": "Blade height or shank size in mm (e.g. 26, 32)"}, {"code": "###", "meaning": "Blade height in mm (e.g. 100, 150)"}, {"code": "####", "meaning": "Shank height x width in mm (e.g. 2525 = 25 x 25)"}]}, {"key": "t-width", "title": "Tool – insert width (seat)", "rows": [{"code": "#", "meaning": "Insert width in mm (the seat's insert, e.g. 3)"}]}, {"key": "t-dia", "title": "Tool – D size", "rows": [{"code": "D##", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D24, D52) (inferred)"}, {"code": "D###", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D120) (inferred)"}]}, {"key": "t-pockets", "title": "Tool – pockets", "rows": [{"code": "#Z", "meaning": "Number of pockets (e.g. 2Z, 4Z)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "JHP", "meaning": "Channels for high-pressure coolant"}, {"code": "MC", "meaning": "Bottom inlets for the high-pressure coolant"}, {"code": "K", "meaning": "With coolant holes (10 bar min.; cooling tube SGCU 341 ordered separately)"}, {"code": "C", "meaning": "With coolant – frontal coolant holes (JETCUT) / internal coolant"}, {"code": "XL", "meaning": "Extra long"}, {"code": "SH", "meaning": "Short head (CNC and Swiss automatics)"}, {"code": "S", "meaning": "Single-sided blade (e.g. TGFH-S) / for next to high shoulders (e.g. PCHRS)"}, {"code": "IQ", "meaning": "IQ line (e.g. TGTR/L-IQ, PCHR/L-D-IQ)"}, {"code": "TR", "meaning": "For TRAUB and Index machines"}, {"code": "MB", "meaning": "For other manufacturers' blocks"}, {"code": "B", "meaning": "B type, e.g. DGTR/L-B-D (reinforced) / DGAD-B-D (screw-clamped) (inferred)"}, {"code": "L###", "meaning": "Tool length in mm (e.g. L120)"}]}]$ck$::jsonb) s
  WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(a."value"::jsonb -> 'sections') x WHERE x ->> 'key' = s ->> 'key')
), '[]'::jsonb))::text
WHERE a."key" = 'codekey.dogrip';
